SET NOCOUNT ON;
BEGIN TRANSACTION;

-- PMT: 1796 lines from PROMED BACK ORDER.xlsx
DELETE FROM ImportedBackorders WHERE SourceCompany = 'PMT';

-- ACM: 1161 lines from ACCESS BACK ORDERS.xlsx
DELETE FROM ImportedBackorders WHERE SourceCompany = 'ACM';

-- PHT: 122 lines from PHARMACARE BACK ORDER.xlsx
DELETE FROM ImportedBackorders WHERE SourceCompany = 'PHT';

-- SBT: 219 lines from SEBENZANI BACK ORDER.xlsx
DELETE FROM ImportedBackorders WHERE SourceCompany = 'SBT';

COMMIT;
SELECT SourceCompany, COUNT(*) AS Lines, SUM(QtyBackOrder) AS Qty, SUM(ExtPrice) AS Value FROM ImportedBackorders GROUP BY SourceCompany ORDER BY SourceCompany;